核心可以这样写，生产环境再按吞吐量把过期清理改成周期任务。

```ts
type Outcome = "processed" | "joined" | "duplicate";

export class MessageGate {
  private readonly inFlight = new Map<string, Promise<void>>();
  private readonly completed = new Map<string, number>();

  constructor(
    private readonly ttlMs: number,
    private readonly now: () => number = Date.now,
  ) {}

  async run(
    platform: string,
    messageId: string | undefined,
    task: () => Promise<void>,
  ): Promise<Outcome> {
    const p = platform.trim();
    const id = messageId?.trim();
    if (!p || !id) {
      await task();
      return "processed";
    }

    const key = JSON.stringify([p, id]);
    const current = this.now();
    const expiresAt = this.completed.get(key);
    if (expiresAt !== undefined && expiresAt > current) return "duplicate";
    if (expiresAt !== undefined) this.completed.delete(key);

    const existing = this.inFlight.get(key);
    if (existing) {
      await existing;
      return "joined";
    }

    const running = (async () => {
      await task();
      this.completed.set(key, this.now() + this.ttlMs);
    })();
    this.inFlight.set(key, running);
    try {
      await running;
      return "processed";
    } finally {
      if (this.inFlight.get(key) === running) this.inFlight.delete(key);
    }
  }
}
